import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('activacion-profetica', 'C',
 [dict(t=1649, e=1691, titulo='Una atmósfera profética', txt='Bueno, Padre, en el nombre de Jesús, desde ahorita armamos una atmósfera profética. Dice que donde está Jesucristo, él es la profecía. Entonces, donde hay un ambiente donde está Cristo, ahí es donde profetizamos. Quiere decir que usted en su casa puede bajar esa atmósfera y puede bajar profecía. […] Lo que usted aprende aquí en esta iglesia no es para que se quede aquí, es para cuando salga, use los dones que Dios le dio y los que se van a activar hoy.'),
  dict(t=2154, e=2200, titulo='El centro es Cristo', txt='[…] pero ese orden no es ni legalista ni libertino. Cuando uno llega al centro, que es Cristo, ¿qué le importa lo que dicen los libertinos? ¿Y qué le importa lo que dicen los legalistas? […] Lo más lindo es estar cristocéntricos, porque entonces el Espíritu Santo nos va a guiar a toda verdad, nos va a revelar todas las cosas, nos va a redargüir de pecado, y usted y yo vamos a ser una iglesia de poder y de fuego.'),
  dict(t=3982, e=4030, titulo='Edificación, exhortación y consolación', txt='Pero el que profetiza habla a los hombres para edificación, exhortación y consolación. El que habla en lenguas a sí mismo se edifica, pero el que profetiza edifica a la iglesia. Entonces, aquí hay tres tipos de personas: los que no hablan en lenguas, los que hablan en lenguas y los que profetizan. ¿En qué grupo está usted? […] Seamos maduros. Otra cosa: la profecía es un mensaje de Dios, no el periódico.')],
 [dict(t=1830, txt='Los profetas discernían las profecías. Tenían el discernimiento de espíritus. Eso lo necesitamos, hermano.'),
  dict(t=3535, txt='Debemos discernir los espíritus que se mueven en la iglesia, y en nuestra casa, y en el trabajo, y donde usted vaya.'),
  dict(t=3787, txt='Procurad alcanzar el amor, pero también desead ardientemente los dones espirituales, sobre todo que profeticéis.')],
 ['Si donde está Cristo se crea una atmósfera profética, ¿qué podrías hacer esta semana para crearla en tu casa o en tu trabajo?',
  '¿Cómo estás cuidando de no irte a los extremos, ni al legalismo ni al libertinaje, y mantener a Cristo en el centro?',
  'De los tres tipos de personas que mencionó (los que no hablan en lenguas, los que hablan en lenguas y los que profetizan), ¿en cuál te ves hoy, y qué paso darías para crecer?'])
